import{_ as e,o as i,c as o,a3 as a}from"./chunks/framework.Cr9EE2ob.js";const m=JSON.parse('{"title":"Submission configuration","description":"Yarilo runs two submission listeners. MX inbound (port 25) is handled by an external MTA (Postfix, Exim, etc.) which delivers to yarilo via LMTP (port 24).","frontmatter":{"outline":[2,4],"head":[["meta",{"name":"robots","content":"noindex"}],["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/protocols/submission.html"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/main/protocols/submission.html"}],["meta",{"property":"og:title","content":"Submission configuration"}],["meta",{"name":"twitter:title","content":"Submission configuration"}],["meta",{"property":"og:description","content":"Yarilo runs two submission listeners. MX inbound (port 25) is handled by an external MTA (Postfix, Exim, etc.) which delivers to yarilo via LMTP (port 24)."}],["meta",{"name":"twitter:description","content":"Yarilo runs two submission listeners. MX inbound (port 25) is handled by an external MTA (Postfix, Exim, etc.) which delivers to yarilo via LMTP (port 24)."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/main/protocols/submission.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/main/protocols/submission.html\\",\\"headline\\":\\"Submission configuration\\",\\"description\\":\\"Yarilo runs two submission listeners. MX inbound (port 25) is handled by an external MTA (Postfix, Exim, etc.) which delivers to yarilo via LMTP (port 24).\\",\\"dateModified\\":\\"2026-10-31T12:43:41.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/main/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Submission configuration\\",\\"item\\":\\"https://doc.yarilomail.org/main/protocols/submission.html\\"}]}]}"]]},"headers":[],"relativePath":"protocols/submission.md","filePath":"protocols/submission.md","lastUpdated":1793450621000}'),t={name:"protocols/submission.md"};function d(r,s,n,l,c,h){return i(),o("div",null,[...s[0]||(s[0]=[a('<h1 id="submission-configuration" tabindex="-1">Submission configuration <a class="header-anchor" href="#submission-configuration" aria-label="Permalink to &quot;Submission configuration&quot;">​</a></h1><p>Yarilo runs two submission listeners. MX inbound (port 25) is handled by an external MTA (Postfix, Exim, etc.) which delivers to yarilo via LMTP (port 24).</p><table tabindex="0"><thead><tr><th style="text-align:left;">Service key</th><th style="text-align:left;">Port</th><th style="text-align:left;">Role</th></tr></thead><tbody><tr><td style="text-align:left;"><code>submission</code></td><td style="text-align:left;"><code>587</code></td><td style="text-align:left;">Outbound submission - AUTH required, STARTTLS.</td></tr><tr><td style="text-align:left;"><code>submissions</code></td><td style="text-align:left;"><code>465</code></td><td style="text-align:left;">Outbound submission - AUTH required, implicit TLS.</td></tr></tbody></table><p>See <a href="/main/architecture/services.html">Services configuration</a> for listener-level settings (<code>port</code>, <code>ssl_<wbr>mode</code>, <code>haproxy_<wbr>protocol</code>, <code>auth_<wbr>allow_<wbr>cleartext</code>).</p><hr><h2 id="protocol-submission" tabindex="-1"><code>protocol.<wbr>submission</code> <a class="header-anchor" href="#protocol-submission" aria-label="Permalink to &quot;`protocol.submission`&quot;">​</a></h2><p>Protocol-level behaviour shared across both submission listeners.</p><h3 id="protocol.submission.hostname" tabindex="-1"><code>hostname</code> <a class="header-anchor" href="#protocol.submission.hostname" aria-label="Permalink to &quot;`hostname` {#protocol.submission.hostname}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>the top-level <code>hostname</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>protocol.submission.hostname</code></dd></dl></div><p>EHLO/HELO banner and <code>Message-ID</code> domain <strong>for submission only</strong>. Unset means the installation&#39;s name; see <a href="/main/installation/general.html">General</a>. Setting it here does not rename the LMTP banner, the <code>Received:</code> header or a delivered message&#39;s <code>Message-ID</code>.</p><h3 id="protocol.submission.submission_max_mail_size" tabindex="-1"><code>submission_<wbr>max_<wbr>mail_<wbr>size</code> <a class="header-anchor" href="#protocol.submission.submission_max_mail_size" aria-label="Permalink to &quot;`submission_max_mail_size` {#protocol.submission.submission_max_mail_size}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>40M</code></dd><dt>Type</dt><dd>string</dd><dt>Also accepted as</dt><dd><code>max_message_size</code></dd><dt>Helm</dt><dd><code>protocol.submission.max_message_size</code></dd></dl></div><p>Maximum accepted message size. Takes a size with a unit (<code>40M</code>) or bytes.</p><h3 id="protocol.submission.max_line_length" tabindex="-1"><code>max_<wbr>line_<wbr>length</code> <a class="header-anchor" href="#protocol.submission.max_line_length" aria-label="Permalink to &quot;`max_line_length` {#protocol.submission.max_line_length}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>4096</code></dd><dt>Type</dt><dd>integer, bytes</dd><dt>Helm</dt><dd><code>protocol.submission.max_line_length</code></dd></dl></div><p>Maximum SMTP command or DATA line length.</p><h3 id="protocol.submission.submission_max_recipients" tabindex="-1"><code>submission_<wbr>max_<wbr>recipients</code> <a class="header-anchor" href="#protocol.submission.submission_max_recipients" aria-label="Permalink to &quot;`submission_max_recipients` {#protocol.submission.submission_max_recipients}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>0</code></dd><dt>Type</dt><dd>integer</dd><dt>Also accepted as</dt><dd><code>max_recipients</code></dd><dt>Helm</dt><dd><code>protocol.submission.max_recipients</code></dd></dl></div><p>Maximum recipients per message. <code>0</code> is unlimited.</p><h3 id="protocol.submission.recipient_delimiter" tabindex="-1"><code>recipient_<wbr>delimiter</code> <a class="header-anchor" href="#protocol.submission.recipient_delimiter" aria-label="Permalink to &quot;`recipient_delimiter` {#protocol.submission.recipient_delimiter}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>+</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>protocol.submission.recipient_delimiter</code></dd></dl></div><p>Subaddress separator: <code>user+tag@domain</code> → <code>user@domain</code>. Empty disables it.</p><h3 id="protocol.submission.submission_client_workarounds" tabindex="-1"><code>submission_<wbr>client_<wbr>workarounds</code> <a class="header-anchor" href="#protocol.submission.submission_client_workarounds" aria-label="Permalink to &quot;`submission_client_workarounds` {#protocol.submission.submission_client_workarounds}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>[]</code></dd><dt>Type</dt><dd>list</dd><dt>Values</dt><dd><code>whitespace-before-path</code> <code>mailbox-for-path</code></dd><dt>Also accepted as</dt><dd><code>client_workarounds</code></dd><dt>Helm</dt><dd><code>protocol.submission.client_workarounds</code></dd><dt>See also</dt><dd><a href="/main/protocols/lmtp.html#protocol.lmtp.lmtp_client_workarounds"><code>lmtp_client_workarounds</code></a></dd></dl></div><p>Compatibility shims for clients that break the protocol. They do the same as the <a href="/main/protocols/lmtp.html#protocol.lmtp.lmtp_client_workarounds">LMTP workarounds</a> of the same name.</p><h3 id="protocol.submission.submission_add_received_header" tabindex="-1"><code>submission_<wbr>add_<wbr>received_<wbr>header</code> <a class="header-anchor" href="#protocol.submission.submission_add_received_header" aria-label="Permalink to &quot;`submission_add_received_header` {#protocol.submission.submission_add_received_header}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>true</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>protocol.submission.add_received_header</code></dd></dl></div><p>Prepend a <code>Received:</code> trace header to messages before forwarding. Set it to <code>false</code> to keep the sender&#39;s address out of the message.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">protocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  submission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    hostname</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mail.example.com</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    submission_max_mail_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">40M</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    max_line_length</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4096</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    submission_max_recipients</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    recipient_delimiter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;+&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    submission_add_received_header</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><hr><h2 id="submission-port-587-465" tabindex="-1">Submission (port 587 / 465) <a class="header-anchor" href="#submission-port-587-465" aria-label="Permalink to &quot;Submission (port 587 / 465)&quot;">​</a></h2><p>Accepts mail from MUAs. AUTH is required. <code>yarilo-submission-login</code> offers <code>PLAIN</code> and <code>LOGIN</code>, plus whatever <code>yarilo-auth</code> runs: the SCRAM mechanisms its passdbs can verify (<code>-PLUS</code> only over TLS 1.3) and, with OAuth2 configured, <code>OAUTHBEARER</code> and <code>XOAUTH2</code> (see <a href="/main/auth/oauth2.html">OAuth 2.0</a>). A refused login answers <code>535</code>; a mechanism not offered answers <code>504</code>. After successful authentication, each transaction is relayed to the configured upstream MTA via <code>protocol.<wbr>submission.<wbr>relay</code> as the client sends it; see <a href="#relay-protocol-submission-relay">Relay</a>. If <code>submission_<wbr>relay_<wbr>host</code> is empty, <code>MAIL FROM</code> is answered <code>451 4.<wbr>3.<wbr>0</code>.</p><p><code>auth_<wbr>allow_<wbr>cleartext: false</code> in the service config blocks AUTH on unencrypted connections; pair it with <code>ssl_<wbr>mode: starttls</code> (port 587) or <code>ssl_<wbr>mode: ssl</code> (port 465).</p><h3 id="a-proxy-in-front" tabindex="-1">A proxy in front <a class="header-anchor" href="#a-proxy-in-front" aria-label="Permalink to &quot;A proxy in front&quot;">​</a></h3><p>A proxy or relay that passes the client&#39;s address with XCLIENT needs <code>xclient_<wbr>protocol: true</code> on the listener and its own network in <code>general.<wbr>xclient.<wbr>trusted_<wbr>nets</code>, which is empty by default. Only a peer in that list sees <code>250-XCLIENT</code> in the EHLO reply and has its forwarded address applied; any other client is not told about XCLIENT. See <a href="/main/installation/general.html#general-xclient">General settings</a>.</p><hr><h2 id="relay-protocol-submission-relay" tabindex="-1">Relay (<code>protocol.<wbr>submission.<wbr>relay</code>) <a class="header-anchor" href="#relay-protocol-submission-relay" aria-label="Permalink to &quot;Relay (`protocol.submission.relay`)&quot;">​</a></h2><p>Configures the upstream MTA for submission. Each transaction gets its own connection, opened at <code>MAIL FROM</code> and closed at the end of <code>DATA</code>, at <code>RSET</code>, or when the client quits or drops. <code>MAIL FROM</code>, every <code>RCPT TO</code> and <code>DATA</code> are passed to the relay as the client sends them, and the relay&#39;s reply, code and text, is the client&#39;s. A recipient the relay refuses is refused at its <code>RCPT TO</code>, and the message still goes to the others. Any transport error returns <code>451 4.<wbr>4.<wbr>0</code> to the MUA; a relay that cannot be reached fails <code>MAIL FROM</code>.</p><p>A client silent for five minutes between commands is disconnected, and its relay transaction with it; <code>submission_<wbr>relay_<wbr>command_<wbr>timeout</code> bounds each relayed command.</p><h3 id="protocol.submission.relay.submission_relay_host" tabindex="-1"><code>submission_<wbr>relay_<wbr>host</code> <a class="header-anchor" href="#protocol.submission.relay.submission_relay_host" aria-label="Permalink to &quot;`submission_relay_host` {#protocol.submission.relay.submission_relay_host}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Also accepted as</dt><dd><code>host</code></dd><dt>Helm</dt><dd><code>protocol.submission.relay.host</code></dd></dl></div><p>Upstream MTA hostname or IP. Empty disables the relay, and submission answers <code>451</code>.</p><h3 id="protocol.submission.relay.submission_relay_port" tabindex="-1"><code>submission_<wbr>relay_<wbr>port</code> <a class="header-anchor" href="#protocol.submission.relay.submission_relay_port" aria-label="Permalink to &quot;`submission_relay_port` {#protocol.submission.relay.submission_relay_port}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>25</code></dd><dt>Type</dt><dd>integer</dd><dt>Also accepted as</dt><dd><code>port</code></dd><dt>Helm</dt><dd><code>protocol.submission.relay.port</code></dd></dl></div><p>Upstream MTA port.</p><h3 id="protocol.submission.relay.submission_relay_user" tabindex="-1"><code>submission_<wbr>relay_<wbr>user</code> <a class="header-anchor" href="#protocol.submission.relay.submission_relay_user" aria-label="Permalink to &quot;`submission_relay_user` {#protocol.submission.relay.submission_relay_user}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Also accepted as</dt><dd><code>user</code></dd><dt>Helm</dt><dd><code>protocol.submission.relay.user</code></dd></dl></div><p>SASL PLAIN username sent to the upstream; <code>%u</code> (or <code>%{user}</code>) is the session&#39;s user. Empty, with no master, sends no AUTH.</p><h3 id="protocol.submission.relay.submission_relay_master_user" tabindex="-1"><code>submission_<wbr>relay_<wbr>master_<wbr>user</code> <a class="header-anchor" href="#protocol.submission.relay.submission_relay_master_user" aria-label="Permalink to &quot;`submission_relay_master_user` {#protocol.submission.relay.submission_relay_master_user}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>protocol.submission.relay.master_user</code></dd></dl></div><p>Log in as this master acting for <code>submission_<wbr>relay_<wbr>user</code> (the SASL authzid), or for the session&#39;s user when that is empty.</p><h3 id="protocol.submission.relay.submission_relay_password" tabindex="-1"><code>submission_<wbr>relay_<wbr>password</code> <a class="header-anchor" href="#protocol.submission.relay.submission_relay_password" aria-label="Permalink to &quot;`submission_relay_password` {#protocol.submission.relay.submission_relay_password}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Also accepted as</dt><dd><code>password</code></dd><dt>Helm</dt><dd><code>protocol.submission.relay.password</code></dd></dl></div><p>SASL PLAIN password, the master&#39;s when one is set. Supports <code>${ENV_<wbr>VAR}</code>. In the chart, <code>relay.<wbr>password_<wbr>secret_<wbr>ref</code> takes it from a Secret instead.</p><h3 id="protocol.submission.relay.submission_relay_ssl" tabindex="-1"><code>submission_<wbr>relay_<wbr>ssl</code> <a class="header-anchor" href="#protocol.submission.relay.submission_relay_ssl" aria-label="Permalink to &quot;`submission_relay_ssl` {#protocol.submission.relay.submission_relay_ssl}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>no</code></dd><dt>Type</dt><dd>string</dd><dt>Values</dt><dd><code>no</code> <code>starttls</code> <code>smtps</code></dd><dt>Also accepted as</dt><dd><code>ssl</code></dd><dt>Helm</dt><dd><code>protocol.submission.relay.ssl</code></dd></dl></div><p>Transport security to the upstream.</p><h3 id="protocol.submission.relay.submission_relay_ssl_verify" tabindex="-1"><code>submission_<wbr>relay_<wbr>ssl_<wbr>verify</code> <a class="header-anchor" href="#protocol.submission.relay.submission_relay_ssl_verify" aria-label="Permalink to &quot;`submission_relay_ssl_verify` {#protocol.submission.relay.submission_relay_ssl_verify}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>true</code></dd><dt>Type</dt><dd>boolean</dd><dt>Also accepted as</dt><dd><code>ssl_verify</code></dd><dt>Helm</dt><dd><code>protocol.submission.relay.ssl_verify</code></dd></dl></div><p>Verify the upstream&#39;s TLS certificate.</p><h3 id="protocol.submission.relay.submission_relay_ssl_ca" tabindex="-1"><code>submission_<wbr>relay_<wbr>ssl_<wbr>ca</code> <a class="header-anchor" href="#protocol.submission.relay.submission_relay_ssl_ca" aria-label="Permalink to &quot;`submission_relay_ssl_ca` {#protocol.submission.relay.submission_relay_ssl_ca}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>protocol.submission.relay.ssl_ca</code></dd></dl></div><p>PEM file the upstream certificate is verified against. Empty means the system roots.</p><h3 id="protocol.submission.relay.submission_relay_trusted" tabindex="-1"><code>submission_<wbr>relay_<wbr>trusted</code> <a class="header-anchor" href="#protocol.submission.relay.submission_relay_trusted" aria-label="Permalink to &quot;`submission_relay_trusted` {#protocol.submission.relay.submission_relay_trusted}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Also accepted as</dt><dd><code>trusted</code></dd><dt>Helm</dt><dd><code>protocol.submission.relay.trusted</code></dd></dl></div><p>Send XCLIENT to the upstream with the client&#39;s real IP. The upstream must advertise XCLIENT.</p><h3 id="protocol.submission.relay.submission_relay_connect_timeout" tabindex="-1"><code>submission_<wbr>relay_<wbr>connect_<wbr>timeout</code> <a class="header-anchor" href="#protocol.submission.relay.submission_relay_connect_timeout" aria-label="Permalink to &quot;`submission_relay_connect_timeout` {#protocol.submission.relay.submission_relay_connect_timeout}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>30</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Also accepted as</dt><dd><code>connect_timeout</code></dd><dt>Helm</dt><dd><code>protocol.submission.relay.connect_timeout</code></dd></dl></div><p>TCP connect timeout.</p><h3 id="protocol.submission.relay.submission_relay_command_timeout" tabindex="-1"><code>submission_<wbr>relay_<wbr>command_<wbr>timeout</code> <a class="header-anchor" href="#protocol.submission.relay.submission_relay_command_timeout" aria-label="Permalink to &quot;`submission_relay_command_timeout` {#protocol.submission.relay.submission_relay_command_timeout}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>300</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Also accepted as</dt><dd><code>command_timeout</code></dd><dt>Helm</dt><dd><code>protocol.submission.relay.command_timeout</code></dd></dl></div><p>Per-command timeout.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">protocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  submission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    relay</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      submission_relay_host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">smtp.example.com</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      submission_relay_port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">587</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      submission_relay_user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">relay-user</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      submission_relay_password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;${RELAY_PASSWORD}&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      submission_relay_ssl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">starttls</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      submission_relay_ssl_verify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      submission_relay_trusted</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      submission_relay_connect_timeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      submission_relay_command_timeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span></span></code></pre></div><h3 id="telling-the-relay-who-sends" tabindex="-1">Telling the relay who sends <a class="header-anchor" href="#telling-the-relay-who-sends" aria-label="Permalink to &quot;Telling the relay who sends&quot;">​</a></h3><p>A relay that authenticates through yarilo, such as Postfix with <code>smtpd_<wbr>sasl_<wbr>type = dovecot</code> pointed at <code>yarilo-sasl-login</code>, can check the sender against the login (<code>reject_<wbr>authenticated_<wbr>sender_<wbr>login_<wbr>mismatch</code>). For that it must see the user, not a service account. Log in as a master acting for each user:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">protocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  submission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    relay</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      submission_relay_host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">relay.example.internal</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      submission_relay_port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">587</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      submission_relay_ssl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">starttls</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      submission_relay_user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%u&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      submission_relay_master_user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">relay-master</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      submission_relay_password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;${YARILO_SUBMISSION_RELAY_PASSWORD}&quot;</span></span></code></pre></div><ul><li><code>relay-master</code> must be a master user in yarilo-auth (see <a href="/main/auth/master_users.html">Master users</a>).</li><li>The session&#39;s user is the one it logged in as, by every mechanism: PLAIN, LOGIN, SCRAM, OAUTHBEARER and XOAUTH2.</li><li>When the relay needs a user (<code>%u</code>, or a master with no relay user) and the session has none, <code>MAIL FROM</code> is refused before the relay is dialled.</li></ul><p>A relay login that fails, or cannot be made for want of a user, answers the client <code>451 4.<wbr>7.<wbr>0 Temporary authentication failure, try again later</code>. The reason is logged with the session id.</p><p>In the Helm chart, <code>relay.<wbr>password_<wbr>secret_<wbr>ref</code> (<code>name</code>, <code>key</code>) gives the password from a Secret to every container that relays, as <code>YARILO_<wbr>SUBMISSION_<wbr>RELAY_<wbr>PASSWORD</code>.</p><h3 id="jmap" tabindex="-1">JMAP <a class="header-anchor" href="#jmap" aria-label="Permalink to &quot;JMAP&quot;">​</a></h3><p>JMAP <code>EmailSubmission</code> sends through this same relay, with the same login as the user and the same limits; see <a href="/main/protocols/jmap.html#sending-mail">JMAP</a>.</p><h3 id="verifying-the-relay" tabindex="-1">Verifying the relay <a class="header-anchor" href="#verifying-the-relay" aria-label="Permalink to &quot;Verifying the relay&quot;">​</a></h3><p>A relay inside the cluster usually holds a certificate from an internal CA. To verify it against that CA, set <code>submission_<wbr>relay_<wbr>ssl_<wbr>ca</code> to the CA&#39;s PEM and keep <code>submission_<wbr>relay_<wbr>ssl_<wbr>verify: true</code>. With <code>internal_<wbr>tls</code> on, the chart already mounts the internal CA at <code>/<wbr>etc/<wbr>yarilo/<wbr>internal-tls/<wbr>ca.<wbr>crt</code>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>2.4.3 and earlier delivered a reply a step behind after AUTH through the login, so a client could not send through Submission.</p></div><p>The pre-beta short names - <code>host</code>, <code>port</code>, <code>user</code>, <code>password</code>, <code>ssl</code>, <code>ssl_<wbr>verify</code>, <code>trusted</code>, <code>connect_<wbr>timeout</code>, <code>command_<wbr>timeout</code> - are still accepted.</p>',85)])])}const u=e(t,[["render",d]]);export{m as __pageData,u as default};
